import { Component, For, Show, useContext } from "solid-js";

import { Link } from "#core/ui-next/components/link.jsx";
import { VSlot } from "#core/ui-next/components/slot.jsx";
import { Tab, TabContext, TabListProps } from "#core/ui-next/components/tab.jsx";

export const TabListLinks: Component<TabListProps> = (props) => {
	const tabContext = useContext(TabContext);

	return (
		<VSlot
			{...props}
			class={`flex flex-col items-end ${props.class ?? ""}`}
			data-name="TabListLinks"
		>
			<For each={tabContext?.tabs()}>
				{(tab, index) => (
					<Tab.Trigger name={tab.name}>
						<Show
							when={!tabContext?.isActive(tab.name)}
							fallback={tab.title()}
						>
							<Link tabIndex={index()}>{tab.title()}</Link>
						</Show>
					</Tab.Trigger>
				)}
			</For>
		</VSlot>
	);
};
